import figma from "figma";

const instance = figma.selectedInstance;

const attr = (name, value) => {
  if (value === undefined || value === false) return "";
  if (value === true) return ` ${name}`;
  if (typeof value === "number") return ` ${name}={${value}}`;
  return value.startsWith("{") ? ` ${name}=${value}` : ` ${name}="${value}"`;
};
const textOf = (node) =>
  node && node.type === "TEXT" ? node.textContent : undefined;

const numSelected = instance.getEnum("Selection", {
  none: 0,
  some: 3,
  all: 10,
});
const download = textOf(
  instance.findText("Label", { path: ["Download"], traverseInstances: true }),
);
const remove = textOf(
  instance.findText("Label", { path: ["Delete"], traverseInstances: true }),
);

export default {
  id: "Bulk actions",
  example: figma.code`<HvBulkActions numTotal={10}${attr("numSelected", numSelected)}
  actions={[
    { id: "download", label: "${download ?? ""}" },
    { id: "delete", label: "${remove ?? ""}" },
  ]}
/>`,
  imports: ['import { HvBulkActions } from "@pentaho/uikit-react-core";'],
  metadata: { nestable: true },
};
